package com.villofarm.controller;
import com.villofarm.dto.OrderDtos.CreateOrderRequest;import com.villofarm.model.CustomerOrder;import com.villofarm.model.OrderItem;import com.villofarm.repository.OrderRepository;import com.villofarm.repository.ProductRepository;import com.villofarm.repository.UserRepository;import jakarta.transaction.Transactional;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.List;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderRepository orders;private final ProductRepository products;private final UserRepository users;public OrderController(OrderRepository orders,ProductRepository products,UserRepository users){this.orders=orders;this.products=products;this.users=users;}@PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public CustomerOrder create(@Valid @RequestBody CreateOrderRequest request,Authentication auth){var order=new CustomerOrder();order.setCustomer(users.findByEmailIgnoreCase(auth.getName()).orElseThrow());order.setDeliveryAddress(request.deliveryAddress());order.setPaymentMethod("CASH_ON_DELIVERY");var total=BigDecimal.ZERO;for(var requested:request.items()){var product=products.findById(requested.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(!product.isActive()||product.getStock()<requested.quantity())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock for "+product.getName());product.setStock(product.getStock()-requested.quantity());var item=new OrderItem();item.setProduct(product);item.setQuantity(requested.quantity());item.setUnitPrice(product.getPrice());order.addItem(item);total=total.add(product.getPrice().multiply(BigDecimal.valueOf(requested.quantity())));}order.setTotal(total);return orders.save(order);}@GetMapping("/my")public List<CustomerOrder> mine(Authentication auth){return orders.findByCustomerEmailOrderByCreatedAtDesc(auth.getName());}}
